      "blocking": "Ellis crouched by the elevator; Mara enters from the hallway.",
      "visible_action": "Ellis jumps back; Mara stops abruptly.",
      "intended_reaction": "Ellis looks startled; Mara looks annoyed.",
      "camera_purpose": "establish the confrontation",
      "performance_intent": "eager, strained",
