        {
          "actor": "ellis",
          "action": "speak",
          "text": "Does the elevator always hum in B-flat?"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "It's a plumbing issue, Ellis. Go back to 3B."
        }
      ],
      "camera_intent": {
        "type": "comedic_wide",
        "subject": "ellis"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
