      "visible_action": "Voss approaches Mara; Ellis retreats behind a pillar.",
      "intended_reaction": "Mara tenses; Voss remains stoic.",
      "camera_purpose": "reveal the antagonist",
      "performance_intent": "bureaucratic, cold",
      "target_start_second": 8.0,
      "actions": [
        {
          "actor": "voss",
          "action": "enter_room"
        },
        {
          "actor": "voss",
          "action": "approach",
          "target": "mara"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "Superintendent. I'm here for the structural audit."
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "Mr. Voss. You're early."
        }
      ],
      "camera_intent": {
        "type": "tension_push",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_3",
      "narrative_purpose": "Ellis tries to sneak past them.",
      "blocking": "Ellis moves toward the elevator; Voss turns to face him.",
      "visible_action": "Ellis freezes; Voss points at him.",
      "intended_reaction": "Ellis looks guilty; Voss looks suspicious.",
      "camera_purpose": "focus on the intruder",
      "performance_intent": "sneaky, suspicious",
      "target_start_second": 16.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "approach",
          "target": "elevator"
        },
        {
          "actor": "voss",
          "action": "point_at",
          "target": "ellis"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "And who is this unauthorized observer?"
        },
        {
          "actor": "ellis",
          "action": "speak",
          "text": "Just... checking the lightbulb!"
        }
      ],
      "camera_intent": {
        "type": "over_the_shoulder",
        "subject": "voss",
        "reaction_subject": "ellis"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_4",
