          "actor": "voss",
          "action": "inspect",
          "target": "elevator"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "The floor indicator is displaying non-standard glyphs."
        }
      ],
      "camera_intent": {
        "type": "insert_object",
        "subject": "elevator"
      },
      "completion_condition": {
        "type": "event_done"
      }
    },
    {
      "id": "beat_5",
