      "visible_action": "Ellis stumbles toward the door; Mara grabs his arm.",
      "intended_reaction": "Ellis panics; Mara struggles.",
      "camera_purpose": "capture the physical chaos",
      "performance_intent": "panicked, desperate",
      "target_start_second": 35.0,
      "actions": [
        {
          "actor": "ellis",
          "action": "flee_to",
          "target": "elevator"
        },
        {
          "actor": "mara",
          "action": "speak",
          "text": "Get back! It's not safe!"
        },
        {
          "actor": "ellis",
          "action": "shout",
          "text": "It's calling my name!"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "This is a major code violation!"
        }
      ],
      "camera_intent": {
        "type": "comedic_wide",
        "subject": "ellis"
      },
      "completion_condition": {
        "type": "dialogue_finished"
      }
    },
    {
      "id": "beat_6",
