      "blocking": "The elevator doors close; the hallway goes quiet.",
      "visible_action": "The doors slam shut; Voss is left standing alone.",
      "intended_reaction": "Voss looks confused; Mara is gone.",
      "camera_purpose": "final comedic beat",
      "performance_intent": "deadpan",
      "target_start_second": 44.0,
      "actions": [
        {
          "actor": "mara",
          "action": "close_elevator"
        },
        {
          "actor": "voss",
          "action": "speak",
          "text": "I'll need to see the maintenance logs for this."
        },
        {
          "actor": "voss",
          "action": "sigh"
        }
      ],
      "camera_intent": {
        "type": "cliffhanger_hold",
        "subject": "voss"
      },
      "completion_condition": {
        "type": "event_done"
      }
    }
  ],
  "payoff": "The elevator doors slam shut, leaving a very confused Inspector Voss alone in the hallway."
